import{_ as t}from"./chunks/9d7754e433cb81649464.Chh4eyeD.js";import{_ as r}from"./chunks/fefc281505d0f59c5ba3.DRN_sfAQ.js";import{_ as a,C as l,o as i,c as s,j as e,a as n,E as m,a6 as h}from"./chunks/framework.CnPv4DE1.js";const P=JSON.parse('{"title":"一人企业商业模式（如何将你自己产品化）","description":"","frontmatter":{"title":"一人企业商业模式（如何将你自己产品化）","originalTitle":"The One-Person Business Model (How To Productize Yourself)","date":"2022-10-08","originalUrl":"https://thedankoe.com/letters/the-one-person-business-model-how-to-monetize-yourself/","minutes":16,"sourceHash":"2b6096a2b079231b0704ec65ec2b32fbb0f1f2268440e9d5002e9cde4b38a6df","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-one-person-business-model-how-to-monetize-yourself/"}]]},"headers":[],"relativePath":"letters/the-one-person-business-model-how-to-monetize-yourself.md","filePath":"letters/the-one-person-business-model-how-to-monetize-yourself.md"}'),c={name:"letters/the-one-person-business-model-how-to-monetize-yourself.md"};function d(u,p,f,b,g,_){const o=l("ArticleMeta");return i(),s("div",null,[p[0]||(p[0]=e("h1",{id:"一人企业商业模式-如何将你自己产品化",tabindex:"-1"},[n("一人企业商业模式（如何将你自己产品化） "),e("a",{class:"header-anchor",href:"#一人企业商业模式-如何将你自己产品化","aria-label":'Permalink to "一人企业商业模式（如何将你自己产品化）"'},"​")],-1)),m(o),p[1]||(p[1]=h('<p><a href="https://www.youtube.com/embed/BZ2nSULolKI?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p><em><strong>少工作。多赚钱。享受生活。</strong></em></p><p>这是我的座右铭。</p><p>成功是反直觉的，而遵循这个座右铭生活为我的人生带来了最大的成长。</p><p>为了休息和恢复而减少工作，能带来更高质量的工作成果。</p><p>赚得更多是一个主观的概念，但我相信任何人都能赚到足够的钱去做他们想做的任何事。</p><p>享受生活通常是这两者的副产品。有了充足的自由时间、资金和商业网络，你这辈子几乎可以做任何你想做的事。</p><p>但是，别担心，我也曾掉进过想要过别人那种生活的陷阱。</p><p>海滨美景。</p><p>脚趾间的沙子。</p><p>晒得像哈塞尔霍夫（Hasslehoff）一样黑。</p><p>插着吸管的椰子，带来那甜美、<em>甜美的</em>电解质，将热带氛围拉满。</p><p>那是在我真正体验过之前。</p><p>一开始感觉棒极了，就像多巴胺跑步机一样，但一旦你拥有了它，那种生活方式很快就会失去光环（除非你通过欣赏、感恩和活在当下，来转换那些为你带来幸福感的神经递质）。</p><p>糟糕的Wi-Fi连接让人厌倦。</p><p>派对和语言障碍让人厌倦。</p><p>在海滩上用笔记本电脑工作让人极度厌倦。</p><p>我的意思是，到底谁真的想那样做？</p><p>你真的想在一个因为阳光太刺眼连屏幕都看不清的地方工作吗？更不用说30分钟后电脑就会过热，你还得乖乖回到室内？</p><p>这封信的目的不是要贬低数字游民的生活方式。我省略了硬币积极的那一面，只是为了在这里描绘一幅画面。看看这是否是适合你的生活方式。</p><p><em>“就像所有事情一样，适度才是有益的。”</em></p><p>正如瓦茨（Watts）所说。</p><p>我在这里就是要谈论这一点。</p><p>适度。</p><p>可持续性。</p><p>一种允许你通过实践、实验和迭代来创造<em>属于你的</em>理想生活方式的商业模式。</p><p>一种利用你的技能、兴趣和志同道合的人来创造创意收入来源的方法。</p><p>一条已经确立并将长久存在的新路径，但由于人们过于受制于自己的信念和舒适的生活方式，它仍然被视为“禁忌”。</p><p>多亏了互联网、思想的碰撞以及多年来构建的解决方案——任何人都可以通过自我教育提升自己的价值，将自己变成一个品牌，并让机会主动找上门来。</p><p>问问你的父母，他们是否能用10到20美元，加上一些自我教育，就能建一个网站、上传产品并接受付款。</p><p>认真的，去问问他们。然后告诉我，为什么你仍然坚信创业需要X、Y和Z。那些已经不再是借口了。</p><p>_你是将此视为一个机会，还是“_<em>只不过是* *那些比我成功的人做的事”？</em></p><p>最棒的是，你现在就可以开始。</p><p>不是等1年后你的技能完美无缺了再开始。</p><p>就是现在。</p><p>如果你正在读这封信，我假设你的年龄在18到35岁之间（也有一些例外情况，我看到你们啦；)）</p><p>这意味着，你拥有18到35年以上的独特人生经验。</p><p>问题出在哪？</p><p><em>你没有看到这种经验中的价值。</em> 你觉得自己的生活很无聊……或者至少无聊到无法通过做自己来获利。这很搞笑，因为有成千上万的人会非常乐意听你讲述为什么你会做你所做的事，<em>他们</em>可不会觉得这很无聊。</p><p>根据我的经验，收入最高的人并不是那些依靠身体或浮夸的生活方式来赚钱的人。</p><p>有<em>深度</em>和<em>价值</em>的人才是收入最高的人。他们不是单维度的。他们像锻炼身体一样锻炼头脑。<em><strong>他们是雇佣专家的通才——而在90%的情况下，那些专家将是被设计来承担重复性任务的机器人。</strong></em> 自动化、无代码工具和10年前根本不存在的软件。</p><blockquote><p>一个人类应该能够换尿布、策划入侵、杀猪、掌舵、设计建筑、写十四行诗、平账、砌墙、接骨、安慰垂死之人、服从命令、下达命令、合作、单干、解方程式、分析新问题、铲粪、给电脑编程、做顿好饭、高效战斗、英勇赴死。<strong>专业化是给昆虫准备的。</strong> ——罗伯特·A·海因莱因（Robert A. Heinlein）</p></blockquote><p>甚至比（看不到你个人经验价值）更严重的问题是：</p><p>你不知道如何以一种让人们能发现其中价值的方式来沟通你的经验。</p><p>这就是所有人在社交媒体上所做的事情。</p><p>有效的沟通。</p><p>有些人比其他人更虚伪，但那是他们的问题。不是你的，也不是我的。</p><p><em>关键不在于变得有趣，而在于学习什么能让你的话语对别人来说变得有趣。</em></p><h2 id="什么是一人企业商业模式" tabindex="-1">什么是一人企业商业模式？ <a class="header-anchor" href="#什么是一人企业商业模式" aria-label="Permalink to &quot;什么是一人企业商业模式？&quot;">​</a></h2><blockquote><p>相比于拥有很多员工，一人企业商业模式一直对我更具吸引力。\\</p><p>一个简单的网站作为“店面”\\</p><p>一组高利润率的数字产品矩阵\\</p><p>每天工作4小时，以及潜在的百万美元年收入\\</p><p>掌控你的工作内容和合作对象。\\</p><p>难以被击败。</p><p>—— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1543915024887971840?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">July 4, 2022</a></p></blockquote><p>在我看来，一人企业是为那些看重自力更生、时间自由和地理位置自由的人准备的。</p><p>我们使用：</p><ul><li>利用社交媒体建立杠杆，吸引志同道合的人，并（从零开始）为自己打响名声</li><li>利用无代码工具和软件建设数字房地产、产品托管和电子邮件列表（这些不像社交媒体那样会被人夺走）</li><li>利用生活方式设计来创造最适合个人的工作日程——通常一开始每天工作2-4小时，有时如果你进入了心流，时间会更长</li></ul><p>这是一个不可思议的时代，活着真好。</p><p>互联网赋予了每个人成为企业家的能力，可以选择自己的工作时间，并围绕自己的痴迷事物来赚取收入。</p><p>没有两个人会痴迷于现实中完全相同的缝隙。而且随着你的进化和经历的增加，没有两个人会痴迷于他们（通过行动和实践）所察觉到的那个特定的现实缝隙。</p><p>当你做得正确时……根本不存在饱和这回事。</p><p>一人企业商业模式是95%的人的最佳选择，尤其是当你刚起步时。每一个十亿美元级别公司的创始人在开启创业之旅时都只有两样东西——一个想法和他们自己。他们并不是一开始就拥有一家十亿美元的公司，但我们往往只相信我们所看到的，并限制了自己的头脑去探索表面之下的东西。</p><p><em>为什么人们的一人企业会失败？</em></p><p>有好几个原因：</p><ul><li>你不相信这是可能的，或者觉得你没有足够的经验</li><li>你没有意识到你业务的每一个方面都是一项需要提升的技能（一开始你会做得很烂）</li><li>你不听取反馈，或者不懂得如何调整你谈论事物的方式（如果你的知识不有趣，你必须通过学习如何思考来<em>让</em>它变得有趣）</li><li>你失去了动力，因为你试图把你的信息搞得过于复杂，以显得独特、聪明和出类拔萃</li></ul><p>这个清单还能列很长。这里的教训是，你必须看重自力更生。你必须把事情掌握在自己手中，并明白没有人会在每个星期五给你发工资。<em>你必须学会狩猎。</em></p><h3 id="零经验开启一人企业的两条路径" tabindex="-1">零经验开启一人企业的两条路径 <a class="header-anchor" href="#零经验开启一人企业的两条路径" aria-label="Permalink to &quot;零经验开启一人企业的两条路径&quot;">​</a></h3><p>最大的杀手是人们不相信商业适合他们，或者觉得自己没有足够的经验。</p><p>首先，别再把商业想得太复杂，它只不过是价值交换。你得到有用的东西，我也得到有用的东西。如果你想在这个围绕金钱运转的世界里真正弄出点动静，就收起你高尚的慈善做派吧。<em>表现得无私只是为了让自己感觉良好，这不过是另一种形式的自私。</em></p><p>如果你在生活中曾用你学过的<em>任何</em>知识帮助过你的朋友或家人，你就已经有足够的经验了。</p><p>进一步说，你觉得经验是怎么来的？</p><p>我告诉你一件事，如果你不踏入竞技场，你<em>不可能</em>获得经验。你是通过在真实世界的环境中实践你的技能来积累经验的。</p><p>如果一个零经验的自由职业者能够去联系客户（为了<em>积累</em>经验）以换取金钱，那你为什么不能在不求任何回报的情况下，在网上发布一些有价值的内容呢？</p><p>让这一切说得通吧。</p><p>你的冒名顶替综合征纯粹是自欺欺人。</p><p>以下是你可以选择的两条路径：</p><h3 id="路径-1-基于技能" tabindex="-1">路径 1) 基于技能 <a class="header-anchor" href="#路径-1-基于技能" aria-label="Permalink to &quot;路径 1) 基于技能&quot;">​</a></h3><p>这是人们告诉你要走的最常见的路线。</p><ol><li>学习一项技能</li><li>教授这项技能</li><li>销售这项技能</li></ol><p>这很好，但正如我所说，你不希望最终变得单维度。你不希望成为那些无法规模化的客户工作的奴隶。你不希望在追求其他事物时却毫无成果可展示。这种事每天都在发生。自由职业者通过冷邮件和推荐赚取收入，而当人类本性开始发挥作用，你想改变方向时，你又得<em>从头</em>开始了。</p><p>去建立一个受众群体，他们的兴趣多样却又相互关联。</p><h3 id="路径-2-基于发展" tabindex="-1">路径 2) 基于发展 <a class="header-anchor" href="#路径-2-基于发展" aria-label="Permalink to &quot;路径 2) 基于发展&quot;">​</a></h3><p>这第二条路线更符合我的节奏。</p><p>它是围绕着4个永恒市场展开的。</p><p>这4个永恒市场存在着迫切且有利可图的问题。这里也是人们拥有崇高目标的地方，而你可以帮助他们实现这些目标。</p><ul><li>健康</li><li>财富</li><li>人际关系</li><li>幸福</li></ul><p>路径1只关注财富。教授适销对路的技能来帮人赚更多钱。默认情况下，你建立的就是一个单维度的品牌。</p><p>通过路径2，你毫不夸张地说是在追求你自己的人生目标（品牌），在追求这些目标的过程中解决你的问题（内容），并创建一个系统来帮助他人做同样的事情（产品/服务）。</p><p>这就是你如何做自己、提升自己，并从自己身上获利的方式。</p><p>“但是 Dan，我才刚起步啊！”</p><p>然后呢？</p><p>你又不是必须写关于“我如何在3天内赚了100万美元”的内容。如今关心这个的人越来越少了。他们在脑子里会直接把它标记为骗局。</p><p>品牌和内容全在于视角。或者用营销的话说叫“定位”。你所要做的就是保持诚实。</p><p>哪个表现会更好？</p><p>“我如何在3天内赚了100万美元”</p><p>还是</p><p>“我计划如何在5年内赚到100万美元”</p><p>你会点击哪一个？你会关注哪一个？你会<em>相信</em>并亲自实践哪一个？</p><p>自我意识和行为改变是你品牌成功的决定性因素。你是否意识到，作为一个局外人，你自己会如何看待你的品牌或内容？你输出的内容真的能改变人们的生活吗？</p><h3 id="路径-3-两者结合" tabindex="-1">路径 3) 两者结合 <a class="header-anchor" href="#路径-3-两者结合" aria-label="Permalink to &quot;路径 3) 两者结合&quot;">​</a></h3><p>当你开启一人企业时，学习使其运转所需的必要技能<em>全靠你自己</em>。</p><p>你将不得不学习如何制作引人注目的头像、背景图、设计，如何撰写有说服力的个人简介和内容，如何创建落地页，以及如何使用别人不知道怎么用的其他软件。</p><p>当然，还有<strong>写作</strong>，这是任何商业成功的基础技能（也是我在<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a>中教授的内容）</p><p>当你谈论实现目标的旅程时，你将通过建立自己的个人品牌来学习技能（通过直接的现实世界经验）。</p><p>然后，如果你脑海中还没有现成的报价（offer），你将<em>拥有</em>可以出售的技能，去帮助其他品牌。</p><p>比如 Jose Rosado，他靠卖个人主页横幅赚到了全职收入，然后转型做网页设计，赚了数十万（multiple 6 figures）。接着他又转型做数字产品。一人企业（one-person business）模式有利于你的个人进化。这就是让你与众不同的地方。</p><p>如果你没看到机会，那是因为你不在竞技场中。这些机会无法进入你的认知，因为你连门都还没进。</p><h2 id="一人企业的4大支柱" tabindex="-1">一人企业的4大支柱 <a class="header-anchor" href="#一人企业的4大支柱" aria-label="Permalink to &quot;一人企业的4大支柱&quot;">​</a></h2><p>对于那些想要做<em>自己想做的事</em>并且去帮助<em>他们最能帮助的人</em>的人来说——传统的品牌、营销、内容和报价创建会把你引向错误的方向。</p><p>个人品牌是我们这个时代最强大的店面。它建立起人与人之间的连接。</p><p>传统的商业模式会让你根据某个存在你能解决的、有利可图的问题的人，来创建一个客户画像。</p><p>我的方法，也就是“经验模式”（The Experience Model），把你变成了客户画像。</p><p><img src="'+t+'" alt=""></p><p>这样一来，你就能解决自己的问题，吸引与你走在相似道路上的人，并帮助他们做到同样的事情。</p><p>另一个好处是，你不需要花费无数个小时去做市场调研来了解什么能卖出去。</p><p>你要做的就是痴迷于实现一个目标，解决随之出现的问题，并创建一个系统来帮助其他人更快地实现它。</p><p>系统只是一个分步指南，说明<em>你</em>会如何倒回去快速解决那个问题。</p><p>就像爬楼梯上了一层楼，然后把电梯降下来帮别人上来。</p><p>你会发现，帮助比你低一个层级的人能获得最好的结果（同时你也会从中学到最多，因为你的认知水平需要能够容纳所有的教导）。</p><h3 id="支柱-1-品牌建设" tabindex="-1">支柱 1) 品牌建设 <a class="header-anchor" href="#支柱-1-品牌建设" aria-label="Permalink to &quot;支柱 1) 品牌建设&quot;">​</a></h3><blockquote><p>在商业中，别再试图去寻找一个要解决的“问题”。\\</p><p>相反，去理解人们试图实现的“目标”。\\</p><p>然后，成为解决那些阻碍人们实现该目标的问题的专家。\\</p><p>帮助他们尽可能快地到达那里。那才是他们想要的。</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1576922278700490753?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">October 3, 2022</a></p></blockquote><p>你的品牌就是你是谁，你做什么，以及你正在做什么。</p><p>你正在为什么<strong>目标</strong>而努力？</p><p>你为什么为之努力？你试图达成的期望结果是什么？这就是人们会关注你的原因。</p><p>品牌建设的特点在于，它不需要在很多地方被直接陈述。也许在你的网站上，你可以解释你的品牌信息，但除此之外——人们会通过你的内容体会到你的品牌信息是什么。</p><h3 id="支柱-2-内容" tabindex="-1">支柱 2) 内容 <a class="header-anchor" href="#支柱-2-内容" aria-label="Permalink to &quot;支柱 2) 内容&quot;">​</a></h3><p>新手需要明白这一点：</p><p>你的品牌（尤其是在社交媒体上）是通过1-3个月的内容形成的。</p><p>内容会产生复利。我指的不是浏览量或覆盖面的复利。我的意思是，信息会在人们的脑海中产生复利，直到你传递的整个信息突然让别人*恍然大悟（clicks）*。</p><p>人们不可能仅凭一条推文、一个视频或一篇文章就理解你。</p><p>如果你想拥有一丁点权威，你在这个游戏中就需要时间（TIME）。</p><p>那么，你该写些什么呢？</p><p>你写那些你计划去精通的兴趣、技能和话题。也就是那些将帮助你以属于你自己的独特方式实现目标的东西。</p><p>还记得上面那条推文吗？关于不要去寻找问题，而是设定目标的那条？</p><p>所有的内容（以及普遍意义上的人类注意力和行为）都围绕着问题展开。问题是你内容的起点，但你<em>和</em>你的关注者必须都在为了相似的目标而努力，这些问题才会显得<em>相关</em>。</p><p>每个人都可以有“过上好日子”的相同目标，但<em>你</em>打算如何将它变成现实？</p><p>对我来说，是通过研究人类心智、哲学和创造性工作来实现。</p><p>对另一个人来说，可能是网页设计、心态和健身。</p><p>对另一个人来说，则可能是自动化、营销和生产力。</p><p><em>如果你把5个人放在山脚下，问他们如何登顶，他们都会画出不同的路线。</em></p><p>这些话题的独特组合就是你的细分领域（niche）。</p><p>它们很宽泛，因为我们想要建立一个庞大、有杠杆作用且灵活的受众群体——而不是把自己关进盒子里，限制我们能谈论的内容。</p><p>如果有一天我想转型做健身，把我（试验了多年）的训练方案变成一门课程，然后靠卖课赚钱，我完全可以。我会以最吸引我受众（他们和我有着相似的目标和兴趣）的方式向他们推销。</p><p>但是，你该<em>如何</em>写这些话题呢？</p><p>在 <a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">Digital Economics</a> 中，我讲授了“精通领域”（Domain Of Mastery）。</p><p><img src="'+r+'" alt=""></p><p>你选择3个<em>宽泛</em>的话题，然后可以把它们分解成原理、激发灵感的导师，以及子话题。</p><p>然后，你可以去研究书籍、播客、文章和社交帖子，看看其他人是如何谈论这些话题的。</p><p>这不仅仅是商业。这是你通过提升自我、学习如何思考并创造有意义的生活来获得报酬的方式。</p><p>明白这只是一个让你<em>向前迈进</em>的起点。当你意识到你真正想做的事情时（因为在你之前的层次，你并没有意识到它），你会转型的。</p><p>一开始，你的任务就是模仿那些行之有效的东西。</p><p>你需要通过撰写一次又一次被证明能保证增长的新手级内容，在你谈论的话题中建立权威。</p><p>去看看你最喜欢的 YouTuber。</p><p>他们一开始是通过酷炫的小 Vlog 来增长受众的吗？</p><p>还是说他们把教育受众、教授他们新技能和新兴趣当成了自己的全职工作？</p><h3 id="支柱-3-报价" tabindex="-1">支柱 3) 报价 <a class="header-anchor" href="#支柱-3-报价" aria-label="Permalink to &quot;支柱 3) 报价&quot;">​</a></h3><p>不，你不需要非得等一阵子才开始变现。我听烦了这种狗屁论调（sh*t）。典型的看门狗（Gatekeeper）心态。</p><p>你需要尽快开始变现（可以先收低价）。</p><p>你<strong>需要</strong>有东西去迭代。你需要有东西去构建、改进，并让它变得更有价值。</p><p>你的第一个报价绝对会很烂。这是逃不掉的。你应该立刻把这第一个糟糕的迭代版本抛出去。</p><p><em>你无法改进不存在的东西。</em></p><p>你需要去体会销售是什么感觉。你需要一个现实世界的载体，把你学到的所有营销和销售知识应用上去。</p><p>“好吧 Dan，那我卖什么？”</p><p>让我向你介绍<strong>最小可行性报价（Minimum Viable Offer，MVO）</strong>。</p><p>MVO 要么是：</p><ol><li>一项单一技能的自由职业服务，你可以卖到 500-1000 美元</li><li>一项单一兴趣的咨询服务，你可以卖包含4次咨询电话的套餐，售价 500-1000 美元</li></ol><p>如果你要加入创作者（creator）经济，我几乎总是推荐选项 2。我不建议从极其耗费时间的客户代工开始，那会让你觉得你根本没时间创作内容。</p><p>（而且，如果你跟我有几分相似，你喜欢自己去学习和尝试。大多数——虽不是全部——创作者都是这样的。我不喜欢让别人替我代劳）。</p><p>健康、表现、心态和商业咨询是理所当然的（热门选项）。</p><p>但是，如果你想卖一项技能而不是兴趣，你依然可以这么做。你只需把它包装成“辅导（tutoring）”。</p><p>你可以辅导或指导人们如何建网站。</p><p>你可以辅导或指导人们如何写作。</p><p>你可以辅导或指导人们如何开始做邮件营销。</p><p>从一个 MVO 开始，特别是如果是 2-4 次咨询电话的套餐，它的美妙之处在哪？</p><p><strong>1) 你可以立刻开始变现。</strong></p><p>如果你懂销售流程，根本不需要落地页。给别人发私信（DM）的能力，一个问卷软件，再加上一个日历预约链接，这就够了。（当然还得有个发账单发票的途径）。</p><p>你接通电话，帮助人们解决问题，并致力于为这些问题研究出有效的解决方案。你一开始不需要所有的答案，你只需要比对方有更多的时间。他们没有时间自己去解决问题。这就是为什么他们愿意为你的服务买单：速度、便利和监督问责（accountability）。</p><p><strong>2) 你可以基于产生的结果，构建出一个可扩展的产品。</strong></p><p>为了增加你咨询服务的价值，你要勾勒出类似课程大纲的东西，来帮助组织通话的结构。你还应该创建像工作表和 Notion 仪表板之类的工具，帮助你的客户取得更多成果。</p><p>随着你受众的增长，这些东西都可以变成产品来出售。产品买家也可以进一步引入你的咨询服务，成为你的客户。</p><p>这意味着，你可以花更少的时间去寻找潜在客户，并且如果你选择减少接纳的客户数量，你会拥有更多的空闲时间（当然，你的价格也会飙升）。</p><h3 id="支柱-4-营销" tabindex="-1">支柱 4) 营销 <a class="header-anchor" href="#支柱-4-营销" aria-label="Permalink to &quot;支柱 4) 营销&quot;">​</a></h3><p>让我们想象一下，你已经创建了你的 MVO。</p><p>你想卖编程辅导服务。</p><p>现在，你需要建立权威和信任，以便把这个服务卖出去。</p><p>因此，你根据新手级的编程话题（这样能接触到更多人，市场上90%都是新手）撰写每周的通讯（newsletter）或长推文连载（thread）。</p><p>你在编程领域与其他人建立人脉网络（network），以便让他们的受众看到你的内容。</p><p>如果你在长推文的底部植入你的服务，并且你的长推文获得了 10万+ 次曝光（这还是最低限度估算），你几乎肯定能拿下你的第一个客户。</p><p>砰的一声（Boom），凭借正确的策略，不再听信脑海中那些限制性的信念，你刚赚到了相当于平均工资三分之一的钱。如果你每周都这么干，不到 3 个月，你的收入就能超过大多数人的工资。</p><p>与自由职业者不同，你在这个过程中还在建立受众。你的内容和推广并没有白费。随着你的成长，你在未来有潜力去卖新的东西。</p><p>关键在于，你需要持续不断地<em>推广</em>自己。</p><p>如果你不去推广你的报价，你就不可能赚到钱。</p><p>就这么简单。</p><p>话虽如此，Digital Economics 现在已经开放报名。</p><p>我为你提供即插即用的系统，让你能够利用现在拥有的技能、兴趣和专业知识，创建一个有效的品牌、内容、报价和营销体系。</p><p>这是一个全面整体的大师班，包含一个完整的 Notion 仪表板（用于运营你的业务）、加速器录播课程，以及一个 Discord 社区，在你建立业务的过程中为你提供个性化的帮助。</p><p>如果你对此感兴趣，并且你已经准备好最终建立一个能够给你带来你所渴望的时间/地点自由的东西，考虑报名吧。</p><p><a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">在这里看看它是否适合你。</a></p><p>– Dan “做你任何想做的事” Koe</p><hr><p><a href="/en/letters/the-one-person-business-model-how-to-monetize-yourself">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',197))])}const x=a(c,[["render",d]]);export{P as __pageData,x as default};
